<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { onLoad, onPullDownRefresh } from '@dcloudio/uni-app'
import WareState from '@/shared/components/WareState.vue'
import { distributionTeamApi, type AccountCandidate, type TeamAccount } from '../../api/distribution-team.api'
const keyword=ref('');const status=ref(1);const list=ref<TeamAccount[]>([]);const configured=ref(true);const teamName=ref('');const loading=ref(true);const error=ref('');const panel=ref<'form'|'bind'|''>('');const editing=ref<TeamAccount>();const candidates=ref<AccountCandidate[]>([]);const candidateKeyword=ref('');const form=reactive({loginName:'',name:'',phone:''})
const title=computed(()=>editing.value?'编辑团队账号':'创建团队账号')
async function load(){loading.value=true;error.value='';try{const data=await distributionTeamApi.accounts(keyword.value,status.value);configured.value=data.configured;teamName.value=data.teamName||'';list.value=data.list}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}
function openForm(row?:TeamAccount){editing.value=row;if(row)Object.assign(form,{loginName:row.login_name,name:row.display_name,phone:row.phone});else Object.assign(form,{loginName:'',name:'',phone:''});panel.value='form'}
async function save(){if(!form.loginName||!form.name||!/^1\d{10}$/.test(form.phone)){uni.showToast({title:'请完整填写账号、姓名和手机号',icon:'none'});return}try{const result=editing.value?await distributionTeamApi.update(editing.value.id,form):await distributionTeamApi.create(form);panel.value='';await load();uni.showToast({title:editing.value?'修改成功':`创建成功，初始密码${(result as any).initialPassword}`,icon:'none'})}catch(e){uni.showToast({title:e instanceof Error?e.message:'保存失败',icon:'none'})}}
async function openBind(){panel.value='bind';candidateKeyword.value='';candidates.value=await distributionTeamApi.candidates('')}
async function searchCandidates(){candidates.value=await distributionTeamApi.candidates(candidateKeyword.value)}
async function bind(row:AccountCandidate){if(!row.bindable)return;await distributionTeamApi.bind(row.id);panel.value='';await load();uni.showToast({title:'绑定成功',icon:'success'})}
function changeState(row:TeamAccount){const next=row.status?0:1;uni.showModal({title:next?'启用账号':'停用账号',content:`确认${next?'启用':'停用'}${row.display_name}的账号？`,success:async r=>{if(r.confirm){await distributionTeamApi.status(row.id,next);load()}}})}
function reset(row:TeamAccount){uni.showModal({title:'重置密码',content:`确认将${row.display_name}的密码重置为 123456？`,success:async r=>{if(r.confirm){await distributionTeamApi.reset(row.id);uni.showToast({title:'密码已重置',icon:'success'})}}})}
onLoad(load);onPullDownRefresh(load)
</script>
<template><view class="page"><view class="team-line"><text>{{teamName||'团队账号'}}</text><text>仅管理本人负责团队</text></view><view class="search"><text>⌕</text><input v-model="keyword" placeholder="姓名、手机号或账号" confirm-type="search" @confirm="load"/><button @click="load">查询</button></view><view class="toolbar"><view class="tabs"><text :class="{active:status===1}" @click="status=1;load()">正常</text><text :class="{active:status===0}" @click="status=0;load()">停用</text></view><view class="actions"><button @click="openBind">绑定账号</button><button class="primary" @click="openForm()">创建账号</button></view></view><WareState v-if="loading" type="loading" title="正在加载团队账号"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重试" @action="load"/><WareState v-else-if="!configured" type="empty" title="当前未配置有效的外包配货团队" description="请联系管理员完成配货团队及负责人配置"/><view v-else-if="list.length" class="list"><view v-for="row in list" :key="row.id" class="card"><view class="head"><view><strong>{{row.display_name}}</strong><text>{{row.phone}}</text></view><text class="badge" :class="{off:!row.status}">{{row.status?'正常':'停用'}}</text></view><view class="meta"><text>登录账号 {{row.login_name}}</text><text>创建于 {{row.create_time.slice(0,10)}}</text></view><view class="card-actions"><text @click="openForm(row)">编辑</text><text @click="reset(row)">重置密码</text><text class="danger" @click="changeState(row)">{{row.status?'停用':'启用'}}</text></view></view></view><WareState v-else type="empty" title="暂无团队账号" description="可绑定已有配货账号或创建新账号"/>
<view v-if="panel" class="mask" @click.self="panel=''" ><view class="drawer"><view class="drawer-head"><strong>{{panel==='form'?title:'绑定已有账号'}}</strong><text @click="panel=''">关闭</text></view><template v-if="panel==='form'"><label>登录账号<input v-model="form.loginName" placeholder="请输入登录账号"/></label><label>真实姓名<input v-model="form.name" placeholder="请输入真实姓名"/></label><label>手机号<input v-model="form.phone" type="number" placeholder="请输入11位手机号"/></label><button class="submit" @click="save">确认保存</button></template><template v-else><view class="candidate-search"><input v-model="candidateKeyword" placeholder="姓名、手机号或账号" @confirm="searchCandidates"/><button @click="searchCandidates">搜索</button></view><scroll-view scroll-y class="candidate-list"><view v-for="row in candidates" :key="row.id" class="candidate"><view><strong>{{row.display_name}}</strong><text>{{row.phone}} · {{row.login_name}}</text><small>{{row.bindable?'未关联团队':`已关联：${row.bound_team_name||'其他团队'}`}}</small></view><button :disabled="!row.bindable" @click="bind(row)">{{row.bindable?'绑定':'不可绑定'}}</button></view></scroll-view></template></view></view></view></template>
<style scoped lang="scss">.page{min-height:100vh;padding:20rpx 24rpx;background:var(--wms-background)}.team-line,.search,.toolbar,.tabs,.actions,.head,.head>view,.meta,.card-actions,.drawer-head,.candidate-search,.candidate{display:flex;align-items:center}.team-line,.toolbar,.head,.drawer-head,.candidate{justify-content:space-between}.team-line{margin-bottom:14rpx}.team-line text:first-child{font-size:25rpx;font-weight:700}.team-line text:last-child{font-size:18rpx;color:var(--wms-text-secondary)}.search{height:68rpx;padding-left:16rpx;border:1rpx solid var(--wms-border);border-radius:10rpx;background:#fff}.search input{flex:1;padding-left:8rpx;font-size:22rpx}.search button,.candidate-search button{height:68rpx;margin:0;border-radius:0 10rpx 10rpx 0;background:var(--wms-primary-700);color:#fff;font-size:20rpx;line-height:68rpx}.toolbar{height:86rpx}.tabs{height:100%;gap:26rpx}.tabs text{display:flex;height:100%;align-items:center;font-size:22rpx}.tabs .active{border-bottom:4rpx solid var(--wms-primary-700);color:var(--wms-primary-700);font-weight:700}.actions{gap:10rpx}.actions button{height:56rpx;margin:0;padding:0 14rpx;border:1rpx solid var(--wms-primary-700);border-radius:8rpx;background:#fff;color:var(--wms-primary-700);font-size:18rpx;line-height:54rpx}.actions .primary{background:var(--wms-primary-700);color:#fff}.list{display:flex;flex-direction:column;gap:12rpx}.card{padding:20rpx;border-radius:16rpx;background:#fff;box-shadow:var(--wms-shadow-card)}.head>view{gap:14rpx}.head strong{font-size:25rpx}.head view text{font-size:20rpx;color:var(--wms-text-secondary)}.badge{padding:5rpx 10rpx;border-radius:6rpx;background:var(--wms-surface-soft);color:var(--wms-success);font-size:18rpx}.badge.off{background:#fbe5e5;color:var(--wms-danger)}.meta{justify-content:space-between;margin-top:14rpx;color:var(--wms-text-secondary);font-size:19rpx}.card-actions{justify-content:flex-end;gap:24rpx;margin-top:16rpx;padding-top:14rpx;border-top:1rpx solid var(--wms-border);color:var(--wms-primary-700);font-size:20rpx}.card-actions .danger{color:var(--wms-danger)}.mask{position:fixed;z-index:99;inset:0;display:flex;align-items:flex-end;background:rgba(23,43,41,.45)}.drawer{box-sizing:border-box;width:100%;max-height:78vh;padding:28rpx 24rpx calc(24rpx + env(safe-area-inset-bottom));border-radius:24rpx 24rpx 0 0;background:#fff}.drawer-head{margin-bottom:22rpx}.drawer-head strong{font-size:28rpx}.drawer-head text{color:var(--wms-primary-700);font-size:20rpx}.drawer label{display:block;margin-top:18rpx;font-size:20rpx;color:var(--wms-text-secondary)}.drawer label input,.candidate-search input{height:68rpx;margin-top:8rpx;padding:0 16rpx;border:1rpx solid var(--wms-border);border-radius:8rpx;font-size:22rpx;color:var(--wms-text-primary)}.submit{height:72rpx;margin-top:28rpx;background:var(--wms-primary-700);color:#fff;font-size:23rpx;line-height:72rpx}.candidate-search input{flex:1;margin:0;border-radius:8rpx 0 0 8rpx}.candidate-list{max-height:55vh;margin-top:18rpx}.candidate{padding:16rpx 0;border-bottom:1rpx solid var(--wms-border)}.candidate>view text,.candidate>view small{display:block;margin-top:5rpx;color:var(--wms-text-secondary);font-size:18rpx}.candidate button{margin:0;font-size:18rpx}.candidate button:not([disabled]){background:var(--wms-primary-700);color:#fff}</style>
